  "claims": [
    {
      "claim": "The closest structural L1 benchmark, a pyridine-sulfonyl piperazine pyrazolopyrimidinone, had 34% absolute oral bioavailability in fasted healthy volunteers, directly supporting F >= 20% for a sulfonamide plus basic-amine scaffold.",
      "card_ids": ["C04"]
    },
    {
      "claim": "Ziprasidone, an aromatic lactam with a basic piperazine, had reported fasted F values of about 30-31% (and up to 60% in one record) and fed F values of about 59-60% across L1/L2 records, all above the 20% threshold.",
      "card_ids": ["C02", "C01", "C37", "C39", "C44", "C49"]
    },
    {
      "claim": "Didanosine, a hydrophilic ionizable nucleoside, had mean absolute F of 29 ± 6% to 42% in fasted patients/children, with a pediatric mean of 0.27 ± 0.13; these estimates do not affirm F < 20%.",
      "card_ids": ["C08", "C12", "C28", "C29", "C40"]
    },
    {
      "claim": "Gaboxadol, a hydrophilic small molecule, had high oral bioavailability in humans and high Fa in rats (83-110%), showing that low logD/high ionization does not by itself imply F < 20%.",
      "card_ids": ["C16", "C26", "C32", "C46", "C47", "C48"]
    },
    {
      "claim": "The available records do not provide a transferable affirmative F < 20% outcome for a relevant analog; didanosine variability (2-89%) and a pediatric 25th percentile of 17% are uncertainty caveats, not affirmative low outcomes.",
      "card_ids": ["C33", "C40"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": [
        "C24", "C25", "C26", "C27", "C28", "C29", "C30", "C31", "C32",
        "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41",
        "C42", "C43", "C44", "C45", "C46", "C47", "C48", "C49", "C50"
      ]
    }
  ],
  "evidence_gaps": [
    "No direct query-specific absolute oral bioavailability or matched oral/IV exposure measurement.",
    "No human PK, formulation, dose, or prandial condition for the query molecule.",
    "No measured permeability, efflux, or first-pass metabolism data for the query.",
    "Structural transfer from analogs is qualitative; differences in core ring system, sulfonamide substituent, and ionization state may alter F.",
    "Didanosine pediatric data show a 25th percentile below 20%, and ziprasidone fasted estimates vary (about 30-60%), adding uncertainty but not affirmative low evidence.",
    "Gaboxadol controlled-release formulation loss in pigs (C25) is formulation-specific and not applicable to the query's unmodified oral context."
  ],
  "decision_summary": "Predicted high because all relevant L1 and L2 records for sulfonamide/basic-amine, lactam/piperazine, and hydrophilic ionizable analogs show mean/point F at or above 20% (e.g., C04 34%, ziprasidone 30-60%, didanosine 27-42%, gaboxadol high/83-110%), and no affirmative threshold-relevant evidence supports F < 20%. Confidence remains low because evidence is transfer-based and query-specific PK is absent."
}

